from fastapi import FastAPI
from pydantic import BaseModel

app = FastAPI()

xp_store = {}

# 预定义成就
ALL_ACHIEVEMENTS = {
    "total_xp_1000": {"name": "千分达人", "condition": lambda xp: xp >= 1000},
    "level_5": {"name": "五级法师", "condition": lambda xp: xp // 1000 + 1 >= 5},
}

user_achievements = {}

class XpGain(BaseModel):
    user_id: int
    amount: int

@app.post("/xp/gain")
async def gain_xp(data: XpGain):
    uid = data.user_id
    if uid not in xp_store: xp_store[uid] = 0
    xp_store[uid] += data.amount
    # 检查成就
    if uid not in user_achievements: user_achievements[uid] = []
    for aid, ach in ALL_ACHIEVEMENTS.items():
        if aid not in user_achievements[uid] and ach["condition"](xp_store[uid]):
            user_achievements[uid].append(aid)
    return {"xp": xp_store[uid]}

# GET /achievements/{user_id}

